direct:
struct S{n:i64}
recursive fn make(n:i64)->S{return S{n:n};}
fn main(){var s:S=make(7);assert(s.n==7);print("direct");}

inline:
struct S{n:i64}
inline fn make(n:i64)->S{S{n:n}}
fn main(){var s:S=make(7);assert(s.n==7);print("inline");}

callback:
struct S{n:i64}
fn apply<F>(n:i64)->i64{var s:S=F(n);s.n}
fn main(){assert(apply(7){n=>S{n:n}}==7);print("callback");}

defer:
struct S{n:i64}
recursive fn make()->S{var s:S=S{n:7};defer{s.n=9;}return s;}
fn main(){var s:S=make();assert(s.n==7);print("defer");}

forward:
struct S{n:i64}
recursive fn make(n:i64)->S{S{n:n}}
recursive fn forward(n:i64)->S{return make(n);}
fn main(){var s:S=forward(7);assert(s.n==7);print("forward");}

global:
struct S{n:i64}
recursive fn make(n:i64)->S{S{n:n}}
var s:S=make(7);
fn main(){assert(s.n==7);print("global");}

discard:
struct S{n:i64}
var calls:i64=0;recursive fn make()->S{calls++;defer{calls++;}return S{n:7};}
fn main(){make();assert(calls==2);print("discard");}

argument:
struct S{n:i64}
recursive fn make()->S{S{n:7}}
recursive fn read(s:S)->i64{return s.n;}
fn main(){assert(read(make())==7);print("argument");}

enum:
enum E{A{n:i64},B}
recursive fn make(n:i64)->E{if n==0{return E.B;}return E.A{n:n};}
fn main(){var a:E=make(7);var b:E=make(0);var sum:i64=0;match a{A p=>sum+=p.n,B=>assert(false)}match b{A p=>assert(false),B=>sum++;}assert(sum==8);print("enum");}
